// Extraire et nettoyer les métadonnées et le texte du cours
const item = $input.first();
const text = item.json.text || '';
const query = $('Webhook Déclencheur (Upload PDF)').first().json.query || {};
const headers = $('Webhook Déclencheur (Upload PDF)').first().json.headers || {};

const otrNumber = Number(query.otr || query.otrNumber || headers['x-otr-number']) || 11;
const lectureName = query.name || query.title || 'Boiterie chez l’enfant (QCM & Synthèse)';
const lectureId = query.id || ('otr_' + String(otrNumber).padStart(2, '0') + '_boiterie_enfant');

const prompt = `Tu es un professeur agrégé et assistant de préparation pédagogique pour le concours de Résidanat en médecine (programme officiel en français).
Transforme ce document médical (cours ou recueil de QCM / annales) en un cours interactif hautement pédagogique, rigoureux et fidèle.

Directives strictes :
- Rigueur médicale absolue : base-toi UNIQUEMENT sur le texte fourni. N'invente aucun chiffre ou seuil non mentionné.
- Si le document est un recueil de QCM : extrais fidèlement chaque QCM avec ses choix (ok: true pour les réponses justes, ok: false pour les fausses) et une explication claire. Synthétise les notions clés en fiches mémo (flashcards) dans "cards", et formule des affirmations Vrai/Faux dans "vf".
- Lie chaque question de quiz et chaque affirmation vf à au moins un identifiant de carte existant dans "cards".

Retourne STRICTEMENT et UNIQUEMENT un objet JSON valide conforme à cette structure :
{
  "schema": 1,
  "id": "${lectureId}",
  "name": "${lectureName}",
  "otrNumber": ${otrNumber},
  "keys": ["Point clé essentiel 1", "Point clé 2"],
  "contrasts": ["Piège classique / Diagnostic différentiel majeur"],
  "cards": [
    { "id": "c1", "type": "basic", "q": "Question courte de révision", "a": "Réponse synthétique", "src": "Section / Page" }
  ],
  "quiz": [
    {
      "id": "q1",
      "q": "Énoncé de la question QCM",
      "src": "Source",
      "cards": ["c1"],
      "explain": "Explication détaillée",
      "opts": [
        { "t": "Proposition A", "ok": true, "c": ["c1"] },
        { "t": "Proposition B", "ok": false }
      ]
    }
  ],
  "vf": [
    {
      "id": "vf1",
      "s": "Affirmation clinique vérifiable",
      "a": true,
      "w": "Explication",
      "cards": ["c1"]
    }
  ]
}

<source_text>
${text.slice(0, 180000)}
</source_text>`;

return {
  json: {
    prompt,
    metadata: {
      id: lectureId,
      name: lectureName,
      otrNumber
    }
  }
};

