// Extraire et valider l'objet JSON retourné par OpenAI
const response = $input.first().json;
const rawContent = response.choices?.[0]?.message?.content || '{}';

let lecture;
try {
  const start = rawContent.indexOf('{');
  const end = rawContent.lastIndexOf('}');
  lecture = JSON.parse(rawContent.substring(start, end + 1));
} catch (err) {
  throw new Error('Erreur de parsing JSON OpenAI: ' + err.message);
}

// Normalisation basique de sécurité
lecture.schema = 1;
if (!Array.isArray(lecture.keys)) lecture.keys = [];
if (!Array.isArray(lecture.contrasts)) lecture.contrasts = [];
if (!Array.isArray(lecture.cards)) lecture.cards = [];
if (!Array.isArray(lecture.quiz)) lecture.quiz = [];
if (!Array.isArray(lecture.vf)) lecture.vf = [];

return {
  json: {
    lecture,
    stats: {
      cards: lecture.cards.length,
      quiz: lecture.quiz.length,
      vf: lecture.vf.length
    }
  }
};
